package vn.aicrm.shared;

import java.util.*;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.stereotype.Service;
import org.springframework.security.core.Authentication;
import org.springframework.http.HttpStatus;
import static vn.aicrm.shared.RetailAccess.*;

@Service
public class RetailPartners {
  private final RetailAccess r;
  private static final List<String> ROLES=List.of("CUSTOMER","SUPPLIER","COLLABORATOR");
  public RetailPartners(RetailAccess r){this.r=r;}
  public static boolean hasRole(RetailAccess r,Map<String,Object> p,String role){return r.node(p.get("roles")).path(role).asBoolean();}
  private boolean accessible(Authentication a,Map<String,Object> p){return List.of("CUSTOMER","SUPPLIER","COLLABORATOR").stream().anyMatch(role->r.node(p.get("roles")).has(role)&&r.granular(a,new RetailPermissions(r).partnerFeature(role),"VIEW"));}
  private String roleFilter(Authentication a){if(!List.of("customer","supplier","partners").stream().anyMatch(f->r.granular(a,f,"VIEW")))return "false";return "("+String.join(" or ",List.of("CUSTOMER","SUPPLIER","COLLABORATOR").stream().filter(role->r.granular(a,new RetailPermissions(r).partnerFeature(role),"VIEW")).map(role->"roles ?? '"+role+"'").toList())+")";}
  private Map<String,Object> visible(Authentication a,Map<String,Object> row){var p=r.clean(row);if(!r.granular(a,"partners","VIEW_BANK"))for(var key:List.of("bank_name","bank_account","bank_holder"))p.remove(key);var visibleRoles=r.json.createObjectNode();for(String role:ROLES)if(r.node(row.get("roles")).has(role)&&r.granular(a,new RetailPermissions(r).partnerFeature(role),"VIEW"))visibleRoles.put(role,r.node(row.get("roles")).path(role).asBoolean());p.put("roles",visibleRoles);return p;}
  public List<Map<String,Object>> catalog(Authentication a){return r.db.queryForList("select * from retail.partner where tenant_id=? order by code",r.tenant(a)).stream().filter(p->accessible(a,p)||hasRole(r,p,"CUSTOMER")&&(r.can(a,"SELL")||r.can(a,"CRM"))||hasRole(r,p,"SUPPLIER")&&r.can(a,"PURCHASE")).map(row->{Map<String,Object> out=new LinkedHashMap<>();for(String k:List.of("id","code","name","phone","email","address","shipping_address","active","customer_group","kind"))out.put(k,row.get(k));var roles=r.json.createObjectNode();for(String role:ROLES)if(hasRole(r,row,role))roles.put(role,true);out.put("roles",roles);return out;}).toList();}
  public Object list(Authentication a,String query,String role,String state,int page,String group){r.require(a,"READ");if(!role.isBlank()&&!r.granular(a,new RetailPermissions(r).partnerFeature(role),"VIEW"))throw problem("PERMISSION_DENIED","Không có quyền xem vai trò đối tác",HttpStatus.FORBIDDEN);if(!role.isBlank()&&!ROLES.contains(role))throw problem("INVALID_ROLE","Vai trò không hợp lệ");if(!Set.of("","ACTIVE","INACTIVE").contains(state))throw problem("INVALID_STATE","Trạng thái không hợp lệ");int offset=Math.max(0,page)*50;String filter="tenant_id=? and "+roleFilter(a)+" and (code ilike ? or name ilike ? or phone ilike ? or email ilike ? or tax_code ilike ?) and (?='' or roles ?? ?) and (?='' or active=?) and (?='' or customer_group=?)";String q="%"+query+"%";Object[] args={r.tenant(a),q,q,q,q,q,role,role,state,state.equals("ACTIVE"),group,group};var total=r.db.queryForObject("select count(*) from retail.partner where "+filter,Long.class,args);var params=new ArrayList<Object>(Arrays.asList(args));params.add(offset);var rows=r.db.queryForList("select * from retail.partner where "+filter+" order by code limit 50 offset ?",params.toArray()).stream().map(p->visible(a,p)).toList();return Map.of("items",rows,"total",total,"page",Math.max(0,page));}
  public Object detail(Authentication a,UUID id){r.require(a,"READ");var partner=r.one("partner",r.tenant(a),id);if(!accessible(a,partner))throw problem("PERMISSION_DENIED","Không có quyền xem đối tác",HttpStatus.FORBIDDEN);var result=visible(a,partner);result.put("history",r.db.queryForList("select d.id,d.number,d.type,d.status,d.total,d.created_at from retail.document d where d.tenant_id=? and d.partner_id=? and "+r.scope(a,"d")+" and ("+r.documentTypes(a,"d","VIEW")+(r.granular(a,"crm","VIEW_HISTORY")?" or d.type in ('POS','ISSUE')":"")+") order by created_at desc limit 500",r.tenant(a),id));if(r.can(a,"FINANCE"))result.put("balances",r.db.queryForList("select o.kind,sum(o.amount-o.credit-o.allocated) remaining from retail.open_item o where o.tenant_id=? and o.partner_id=? and "+r.branchScope(a,"o")+" and "+new RetailFinance(r,null).debtFilter(a,"o")+" group by o.kind",r.tenant(a),id));if(r.can(a,"CRM"))result.put("notes",r.db.queryForList("select c.* from retail.care c where c.tenant_id=? and c.partner_id=? and "+r.branchScope(a,"c")+" order by created_at desc limit 500",r.tenant(a),id));result.put("warnings",r.db.queryForList("select id,code,name from retail.partner where tenant_id=? and id<>? and ((?<>'' and phone=?) or (?<>'' and lower(email)=lower(?)))",r.tenant(a),id,result.get("phone"),result.get("phone"),result.get("email"),result.get("email")));return result;}
  public Object save(Authentication a,UUID id,JsonNode x){return save(a,id,x,false);}
  public Object quickCustomer(Authentication a,JsonNode x){r.gate(a,"customer","CREATE");var clean=r.json.createObjectNode();for(String key:List.of("code","name","entityType","phone","email","address"))if(x.has(key))clean.set(key,x.get(key));clean.put("shippingAddress",text(x,"address",""));clean.putObject("roles").put("CUSTOMER",true);return save(a,null,clean,false,true);}
  private Object save(Authentication a,UUID id,JsonNode x,boolean preview){return save(a,id,x,preview,false);}
  private Object save(Authentication a,UUID id,JsonNode x,boolean preview,boolean quickCustomer){new RetailPermissions(r).partnerWrite(a,id,x);var t=r.tenant(a);var old=id==null?null:r.one("partner",t,id);if(old!=null&&(!x.has("version")||x.path("version").asInt(-1)!=((Number)old.get("version")).intValue()))throw problem("VERSION_CONFLICT","Hồ sơ đã thay đổi; tải lại trước khi lưu",HttpStatus.CONFLICT);
    String code=required(x,"code",60),name=required(x,"name",160),entity=text(x,"entityType","PERSON");if(!Set.of("PERSON","BUSINESS").contains(entity))throw problem("INVALID_PARTNER","Loại đối tượng không hợp lệ");var roles=r.json.createObjectNode();if(x.has("roles")){if(!x.path("roles").isObject())throw problem("INVALID_ROLE","Vai trò phải là danh sách trạng thái");x.path("roles").fields().forEachRemaining(e->{if(!ROLES.contains(e.getKey())||!e.getValue().isBoolean())throw problem("INVALID_ROLE","Vai trò không hợp lệ");roles.put(e.getKey(),e.getValue().asBoolean());});}else {String kind=text(x,"kind","CUSTOMER");if(!ROLES.contains(kind))throw problem("INVALID_ROLE","Vai trò không hợp lệ");roles.put(kind,true);}if(roles.isEmpty())throw problem("INVALID_ROLE","Chọn ít nhất một vai trò");
    if(old!=null&&x.path("roles").isObject()){var priorRoles=r.node(old.get("roles"));for(String role:ROLES)if(priorRoles.has(role)&&!roles.has(role))roles.set(role,priorRoles.get(role));}
    boolean active=x.path("active").asBoolean(true);if(old!=null){var prior=r.node(old.get("roles"));for(String role:ROLES)if(prior.path(role).asBoolean()&&!roles.path(role).asBoolean()){String types=role.equals("SUPPLIER")?"'PURCHASE_REQUEST','PURCHASE_ORDER','PURCHASE_RECEIPT','PURCHASE_RETURN'":role.equals("CUSTOMER")?"'QUOTE','SALE_ORDER','POS','ISSUE'":"'SALE_ORDER'";if(r.db.queryForObject("select count(*) from retail.document where tenant_id=? and partner_id=? and status in ('DRAFT','PENDING','APPROVED','PARTIAL') and type in ("+types+")",Integer.class,t,id)>0)throw problem("ROLE_IN_USE","Vai trò còn chứng từ đang xử lý; hoàn tất hoặc hủy trước");}}
    String tax=text(x,"taxCode","").replaceAll("[\\s.-]","").toUpperCase(Locale.ROOT);if(!tax.isEmpty()&&!tax.matches("[A-Z0-9]{5,30}"))throw problem("INVALID_TAX","Mã số thuế không hợp lệ");if(r.db.queryForObject("select count(*) from retail.partner where tenant_id=? and (code=? or (?<>'' and tax_code=?)) and (?::uuid is null or id<>?::uuid)",Integer.class,t,code,tax,tax,id,id)>0)throw problem("PARTNER_DUPLICATE","Mã đối tác hoặc mã số thuế đã có; chọn hồ sơ hiện hữu");
    String phone=bounded(x,"phone",60),email=bounded(x,"email",160);if(!email.isBlank()&&!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw problem("INVALID_EMAIL","Email không hợp lệ");UUID owner=optional(x,"ownerId");if(owner!=null&&r.db.queryForObject("select count(*) from identity.account where tenant_id=? and id=? and enabled",Integer.class,t,owner)==0)throw problem("INVALID_OWNER","Người phụ trách không thuộc công ty");
    if(x.path("supplierProfile").asBoolean(false)){if(!roles.has("SUPPLIER"))throw problem("INVALID_ROLE","Hồ sơ NCC cần vai trò Nhà cung cấp");required(x,"entityType",15);required(x,"phone",60);required(x,"email",160);required(x,"address",2000);}
    String companyName=x.has("companyName")?bounded(x,"companyName",160):old==null?"":String.valueOf(old.get("company_name"));
    String companyAddress=x.has("companyAddress")?bounded(x,"companyAddress",2000):old==null?"":String.valueOf(old.get("company_address"));
    Integer saleDays=days(x,"saleDays"),purchaseDays=days(x,"purchaseDays");String bank=old==null?"":String.valueOf(old.get("bank_name")),account=old==null?"":String.valueOf(old.get("bank_account")),holder=old==null?"":String.valueOf(old.get("bank_holder"));if(x.has("bankName")||x.has("bankAccount")||x.has("bankHolder")){r.gate(a,"partners","UPDATE_BANK");bank=bounded(x,"bankName",160);account=bounded(x,"bankAccount",80);holder=bounded(x,"bankHolder",160);}
    if(preview)return Map.of("ok",true);UUID target=id==null?UUID.randomUUID():id;String kind=ROLES.stream().filter(roles::has).findFirst().orElseThrow();if(old==null)r.db.update("insert into retail.partner(id,tenant_id,code,name,kind,roles,created_by) values(?,?,?,?,?,?::jsonb,?)",target,t,code,name,kind,roles.toString(),r.actor(a));
    r.db.update("update retail.partner set code=?,name=?,kind=?,roles=?::jsonb,entity_type=?,company_name=?,company_address=?,tax_code=?,phone=?,email=?,address=?,shipping_address=?,customer_group=?,contact_name=?,contact_title=?,contact_phone=?,sale_terms=?,purchase_terms=?,sale_days=?,purchase_days=?,bank_name=?,bank_account=?,bank_holder=?,owner_id=?,active=?,version=version+1,updated_at=now(),updated_by=? where tenant_id=? and id=?",code,name,kind,roles.toString(),entity,companyName,companyAddress,tax,phone,email,bounded(x,"address",2000),bounded(x,"shippingAddress",2000),bounded(x,"customerGroup",80),bounded(x,"contactName",160),bounded(x,"contactTitle",80),bounded(x,"contactPhone",60),bounded(x,"saleTerms",500),bounded(x,"purchaseTerms",500),saleDays,purchaseDays,bank,account,holder,owner,active,r.actor(a),t,target);
    return detail(a,target);
  }
  public Object importPartner(Authentication a,JsonNode input,boolean preview){r.require(a,"SETUP");var x=(com.fasterxml.jackson.databind.node.ObjectNode)input.deepCopy();if(x.path("roles").isTextual()){var parsed=r.json.createObjectNode();for(String role:x.path("roles").asText().split("[,;|]"))parsed.put(role.trim(),true);x.set("roles",parsed);}var existing=r.db.queryForList("select * from retail.partner where tenant_id=? and code=?",r.tenant(a),required(x,"code",60));UUID id=existing.isEmpty()?null:(UUID)existing.getFirst().get("id");var body=existing.isEmpty()?r.json.createObjectNode():body(existing.getFirst(),r.can(a,"FINANCE"));x.fields().forEachRemaining(e->body.set(e.getKey(),e.getValue()));if(id!=null){var merged=(com.fasterxml.jackson.databind.node.ObjectNode)r.node(existing.getFirst().get("roles")).deepCopy();if(x.path("roles").isObject())x.path("roles").fields().forEachRemaining(e->merged.set(e.getKey(),e.getValue()));else if(x.has("kind"))merged.put(text(x,"kind","CUSTOMER"),true);body.set("roles",merged);}return save(a,id,body,preview);}
  private com.fasterxml.jackson.databind.node.ObjectNode body(Map<String,Object> row,boolean finance){var out=r.json.createObjectNode();for(String k:List.of("code","name","phone","email","address","active","version"))out.set(k,r.json.valueToTree(row.get(k)));out.set("roles",r.node(row.get("roles")));for(String pair:List.of("entityType:entity_type","companyName:company_name","companyAddress:company_address","taxCode:tax_code","shippingAddress:shipping_address","customerGroup:customer_group","contactName:contact_name","contactTitle:contact_title","contactPhone:contact_phone","saleTerms:sale_terms","purchaseTerms:purchase_terms","saleDays:sale_days","purchaseDays:purchase_days","ownerId:owner_id")){var parts=pair.split(":");out.set(parts[0],r.json.valueToTree(row.get(parts[1])));}if(finance)for(String pair:List.of("bankName:bank_name","bankAccount:bank_account","bankHolder:bank_holder")){var parts=pair.split(":");out.set(parts[0],r.json.valueToTree(row.get(parts[1])));}return out;}
  public Object deactivate(Authentication a,UUID id){var p=r.one("partner",r.tenant(a),id);var x=body(p,r.can(a,"FINANCE"));x.put("active",false);return save(a,id,x);}
  private String historyScope(Authentication a){var types=new ArrayList<String>();if(r.can(a,"SELL"))types.addAll(List.of("QUOTE","SALE_ORDER","POS","ISSUE","SALE_RETURN"));if(r.can(a,"PURCHASE"))types.addAll(List.of("PURCHASE_REQUEST","PURCHASE_ORDER","PURCHASE_RECEIPT","PURCHASE_RETURN"));if(r.can(a,"FINANCE"))types.addAll(List.of("OPENING_AR","OPENING_AP","REFUND"));if(r.can(a,"CRM"))types.addAll(List.of("POS","ISSUE"));return types.isEmpty()?"false":"d.type in ('"+String.join("','",types)+"')";}
  public Object accounts(Authentication a){r.require(a,"SETUP");return r.db.queryForList("select id,display_name from identity.account where tenant_id=? and enabled order by display_name",r.tenant(a));}
  private String bounded(JsonNode x,String key,int max){String value=text(x,key,"");if(value.length()>max)throw problem("INVALID_FIELD",key+" vượt độ dài cho phép");return value;}
  private Integer days(JsonNode x,String key){if(!x.hasNonNull(key)||x.path(key).asText().isBlank())return null;String value=x.path(key).asText();if(!value.matches("[0-9]{1,4}")||Integer.parseInt(value)>3650)throw problem("INVALID_TERMS","Số ngày thanh toán từ 0 đến 3650");return Integer.valueOf(value);}
}
